F="Keep the exact same camera, composition, architecture, painted 3D finish with black ink contours and halftone in the shadows. No text, no letters, no numbers, no logos."
j(){ python3 -c 'import json,sys;print(json.dumps({"prompt":sys.argv[1],"aspect_ratio":sys.argv[2],"resolution":"1K","quality":"medium","output_format":"png","num_outputs":1}))' "$1" "$2"; }
python3 hd.py vault-empty gpt-image-2 "$(j "The same bank vault, but the floor is completely empty and swept clean: no gold coins at all, bare stone floor in front of the bare steel wall. $F" 9:16)" img/vault-full.jpg > log-vault-empty.txt 2>&1 &
for w in "" "-w"; do A=9:16; [ "$w" = "-w" ] && A=16:9
python3 hd.py exch-am$w gpt-image-2 "$(j "The same trading floor in the same morning light, but the brass bell and its iron bracket are removed from the left wall: plain wall there. The big clock face stays completely blank. $F" $A)" img/exch-day$w.jpg > log-am$w.txt 2>&1 &
python3 hd.py exch-close$w gpt-image-2 "$(j "The same trading floor at the closing bell, late afternoon: low golden-orange sunlight raking through the tall windows, the floor packed with traders in waistcoats and shirtsleeves shouting and throwing paper slips into the air, slips falling everywhere. The brass bell and its iron bracket are removed from the left wall: plain wall there. The big clock face stays completely blank. $F" $A)" img/exch-day$w.jpg > log-close$w.txt 2>&1 &
python3 hd.py exch-night$w gpt-image-2 "$(j "The same trading floor at night, closed and empty: deep blue moonlight through the tall windows, one green banker's lamp still lit on a trading post, paper slips littering the floor, chairs on desks, long shadows. The brass bell and its iron bracket are removed from the left wall: plain wall there. The big clock face stays completely blank and dimly lit. $F" $A)" img/exch-day$w.jpg > log-night$w.txt 2>&1 &
done; wait
